use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn find(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if k == x { return true }
            if x < k { cur = self.left[cur as usize] } else { cur = self.right[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.find(x) { return false }
        let id = self.keys.len() as int
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut cur = self.root
        loop {
            let c = cur as usize
            if x < self.keys[c] {
                if self.left[c] < 0 { self.left[c] = id
                    return true }
                cur = self.left[c]
            } else {
                if self.right[c] < 0 { self.right[c] = id
                    return true }
                cur = self.right[c]
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.left[parent as usize] == old {
            self.left[parent as usize] = new
        } else {
            self.right[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur >= 0 && self.keys[cur as usize] != x {
            parent = cur
            if x < self.keys[cur as usize] { cur = self.left[cur as usize] } else { cur = self.right[cur as usize] }
        }
        if cur < 0 { return false }
        let c = cur as usize
        let l = self.left[c]
        let r = self.right[c]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            while self.left[s as usize] >= 0 {
                sp = s
                s = self.left[s as usize]
            }
            self.keys[c] = self.keys[s as usize]
            let sr = self.right[s as usize]
            self.replace_child(sp, s, sr)
        } else if l >= 0 {
            self.replace_child(parent, cur, l)
        } else {
            self.replace_child(parent, cur, r)
        }
        true
    }

    fn height(self, i: int) -> int {
        if i < 0 { return 0 }
        let a = self.height(self.left[i as usize])
        let b = self.height(self.right[i as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.left[cur as usize]
            }
            let n = stack.pop().unwrap_or(0)
            out.push("${self.keys[n as usize]}")
            cur = self.right[n as usize]
        }
        if out.len() == 0 { return "<empty>" }
        out.join(" ")
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.find(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut cur = t.root
                if cmd == "min" {
                    while t.left[cur as usize] >= 0 { cur = t.left[cur as usize] }
                } else {
                    while t.right[cur as usize] >= 0 { cur = t.right[cur as usize] }
                }
                println("${t.keys[cur as usize]}")
            }
        }
    }
}

